package org.opened.app.core.source

/**
 * Categorization of empirical and scholarly evidence for lessons generated by openED.
 * Distinguishes between settled facts, working scientific hypotheses, historiographical interpretations,
 * and unverified claims.
 */
enum class EvidenceQuality(
    val id: String,
    val displayName: String,
    val badgeText: String,
    val description: String
) {
    ESTABLISHED_FACT(
        id = "established_fact",
        displayName = "Established Fact",
        badgeText = "✅ Established Fact",
        description = "Empirically verified, scientific consensus, or primary legal/historical documentation"
    ),
    HYPOTHESIS(
        id = "hypothesis",
        displayName = "Working Hypothesis",
        badgeText = "🔬 Hypothesis",
        description = "Plausible scientific theory or model currently under empirical investigation"
    ),
    INTERPRETATION(
        id = "interpretation",
        displayName = "Academic Interpretation",
        badgeText = "⚖️ Interpretation",
        description = "Historiographical, economic, or philosophical school of thought with competing viewpoints"
    ),
    INFERENCE(
        id = "inference",
        displayName = "Logical Inference",
        badgeText = "💡 Inference",
        description = "Deductive or inductive conclusion derived from primary observations"
    ),
    UNVERIFIED_CLAIM(
        id = "unverified_claim",
        displayName = "Unverified Claim",
        badgeText = "⚠️ Unverified Claim",
        description = "Preliminary assertion requiring further primary source replication or verification"
    );

    companion object {
        fun fromString(str: String?): EvidenceQuality {
            if (str == null) return ESTABLISHED_FACT
            val lower = str.lowercase()
            return when {
                lower.contains("fact") || lower.contains("consensus") || lower.contains("established") -> ESTABLISHED_FACT
                lower.contains("hypoth") || lower.contains("theory") || lower.contains("model") -> HYPOTHESIS
                lower.contains("interpret") || lower.contains("perspective") || lower.contains("school") || lower.contains("disputed") -> INTERPRETATION
                lower.contains("infer") || lower.contains("deduct") -> INFERENCE
                lower.contains("unverified") || lower.contains("claim") || lower.contains("tentative") -> UNVERIFIED_CLAIM
                else -> ESTABLISHED_FACT
            }
        }
    }
}
